import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Pie } from 'react-chartjs-2';
import { Chart, ArcElement, Tooltip, Legend } from 'chart.js';

Chart.register(ArcElement, Tooltip, Legend);
const Dashboard = () => {


  const userName = localStorage.getItem('userName');
  const userId = localStorage.getItem('userId');
  const navigate = useNavigate();

  const [expenses, setExpenses] = useState([]);
  const [todayTotal, setTodayTotal] = useState(0);
  const [yesterdayTotal, setYesterdayTotal] = useState(0);
  const [last7DaysTotal, setLast7DaysTotal] = useState(0);
  const [last30DaysTotal, setLast30DaysTotal] = useState(0);
  const [currentyearTotal, setCurrentyearTotal] = useState(0);
  const [grandTotal, setGrandTotal] = useState(0);


  const pieData = {
    labels: expenses.map(exp => exp.ExpenseItem),
    datasets: [
      {
        label: 'Expense Cost',
        data: expenses.map(exp => parseFloat(exp.ExpenseCost)),
        backgroundColor: [
          'red',
          'blue',
          '#00ff00',
          'rgba(80, 10, 45, 0.5)',
          'yellow',
          'orange',
          'purple',
          'pink'
        ],
        borderWidth: 1,
      },
    ],
  }
  useEffect(() => {
    if (!userId) {
      navigate('/login');
      return;
    }
    fetchExpenses();
  }, [userId, navigate]);

  const fetchExpenses = async () => {
    try {
      const response = await fetch(
        `http://127.0.0.1:8000/api/manage_expense/${userId}/`
      );

      const data = await response.json();
      const expenses = Array.isArray(data) ? data : [];
      setExpenses(expenses);

      calculateTotals(expenses);
    } catch (error) {
      console.error("Error fetching expenses:", error);
    }
  };

  const calculateTotals = (data) => {
    const today = new Date();
    const todayStr = today.toDateString();

    const yesterday = new Date();
    yesterday.setDate(today.getDate() - 1);
    const yesterdayStr = yesterday.toDateString();

    const last7 = new Date();
    last7.setDate(today.getDate() - 7);

    const last30 = new Date();
    last30.setDate(today.getDate() - 30);

    const currentYear = today.getFullYear();

    let todaySum = 0;
    let yesterdaySum = 0;
    let last7Sum = 0;
    let last30Sum = 0;
    let yearSum = 0;
    let grandSum = 0;

    data.forEach((item) => {
      const date = new Date(item.ExpenseDate);
      const amount = parseFloat(item.ExpenseCost) || 0;

      grandSum += amount;

      if (date.toDateString() === todayStr) todaySum += amount;
      if (date.toDateString() === yesterdayStr) yesterdaySum += amount;
      if (date >= last7) last7Sum += amount;
      if (date >= last30) last30Sum += amount;
      if (date.getFullYear() === currentYear) yearSum += amount;
    });

    setTodayTotal(todaySum);
    setYesterdayTotal(yesterdaySum);
    setLast7DaysTotal(last7Sum);
    setLast30DaysTotal(last30Sum);
    setCurrentyearTotal(yearSum);
    setGrandTotal(grandSum);
  };

  return (
    <div className='container mt-4'>

      <div className='text-center mb-4'>
        <h2>Welcome, {userName}!</h2>
        <p className='text-muted'>Here's your expense overview</p>
      </div>

      {/* ROW 1 */}
      <div className='row g-4'>

        <div className='col-md-4'>
          <div className='card bg-primary text-white text-center' style={{ height: '150px' }}>
            <div className='card-body'>
              <h5>
                <i className="fas fa-calendar-day me-2"></i>
                Today's Expense
              </h5>
              <h4>₹ {todayTotal}</h4>
            </div>
          </div>
        </div>

        <div className='col-md-4'>
          <div className='card bg-secondary text-white text-center' style={{ height: '150px' }}>
            <div className='card-body'>
              <h5>
                <i className="fas fa-calendar-minus me-2"></i>
                Yesterday Expense
              </h5>
              <h4>₹ {yesterdayTotal}</h4>
            </div>
          </div>
        </div>

        <div className='col-md-4'>
          <div className='card bg-info text-white text-center' style={{ height: '150px' }}>
            <div className='card-body'>
              <h5>
                <i className="fas fa-calendar-week me-2"></i>
                Last 7 Days
              </h5>
              <h4>₹ {last7DaysTotal}</h4>
            </div>
          </div>
        </div>

      </div>

      {/* ROW 2 */}
      <div className='row g-4 mt-1'>

        <div className='col-md-4'>
          <div className='card bg-success text-white text-center' style={{ height: '150px' }}>
            <div className='card-body'>
              <h5>
                <i className="fas fa-calendar-alt me-2"></i>
                Last 30 Days
              </h5>
              <h4>₹ {last30DaysTotal}</h4>
            </div>
          </div>
        </div>

        <div className='col-md-4'>
          <div className='card bg-warning text-white text-center' style={{ height: '150px' }}>
            <div className='card-body'>
              <h5>
                <i className="fas fa-chart-line me-2"></i>
                Current Year
              </h5>
              <h4>₹ {currentyearTotal}</h4>
            </div>
          </div>
        </div>

        <div className='col-md-4'>
          <div className='card bg-danger text-white text-center' style={{ height: '150px' }}>
            <div className='card-body'>
              <h5>
                <i className="fas fa-wallet me-2"></i>
                Grand Total
              </h5>
              <h4>₹ {grandTotal}</h4>
            </div>
          </div>
        </div>

      </div>

      <div className="my-5" style={{ width: '400px', height: '400px', margin: 'auto' }}>
        <h4 className='text-center'>Expense Distribution</h4>
        <Pie data={pieData} />
      </div>

    </div>
  );
};

export default Dashboard;