import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { useNavigate } from 'react-router-dom';

const ManageExpense = () => {
  const navigate = useNavigate();

  const [expenses, setExpenses] = useState([]);
  const [editExpense, setEditExpense] = useState(null);

  const userId = localStorage.getItem("userId");

  useEffect(() => {
    if (!userId || userId === "undefined" || userId === "null") {
      navigate("/login");
      return;
    }

    fetchExpenses();
  }, [userId, navigate]);

  const fetchExpenses = async () => {
    try {
      const response = await fetch(
        `http://127.0.0.1:8000/api/manage_expense/${userId}/`
      );

      const data = await response.json();
      setExpenses(Array.isArray(data) ? data : []);

    } catch (error) {
      console.error(error);
    }
  };

  const handleUpdate = async () => {
    try {
      const response = await fetch(
        `http://127.0.0.1:8000/api/update_expense/${editExpense.id}/`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(editExpense),
        }
      );

      if (response.status === 200) {
        toast.success(" Expense updated successfully!");
        setEditExpense(null);
        fetchExpenses();
      }

    } catch (error) {
      console.error(error);
    }
  };

   const handleDelete = async (expenseId) => {
      if(window.confirm('Are you sure you want to delete this expense?')){
    try {
      const response = await fetch(
        `http://127.0.0.1:8000/api/delete_expense/${expenseId}/`,
        {
          method: 'DELETE',
          
        });

      if (response.status === 200) {
        toast.success(" Expense deleted successfully!");
        fetchExpenses(userId);
      }
      else {
        toast.error('Failed to delete expense');
      }
    } catch (error) {
      console.error("Error deleting expenses: ", error);
      toast.error('Something went wrong');
    }
  }
  };

  return (
    <div className="container mt-5">

      <div className="text-center mb-4">
        <h2>
          <i className="fas fa-tasks me-2"></i>
          Manage Expense
        </h2>
        <p className="text-muted">
          View, edit, or delete your expenses
        </p>
      </div>

      <div>
        <table className="table table-striped table-bordered">
          <thead className="table-dark text-center">
            <tr>
              <th>#</th>
              <th>Date</th>
              <th>Item</th>
              <th>Cost (₹)</th>
              <th>Action</th>
            </tr>
          </thead>

          <tbody>
            {expenses.length > 0 ? (
              expenses.map((exp, index) => (
                <tr key={exp.id || index}>
                  <td>{index + 1}</td>

                  {/* DATE */}
                  <td>
                    {editExpense && editExpense.id === exp.id ? (
                      <input
                        type="date"
                        value={editExpense.ExpenseDate}
                        onChange={(e) =>
                          setEditExpense({
                            ...editExpense,
                            ExpenseDate: e.target.value
                          })
                        }
                      />
                    ) : (
                      exp.ExpenseDate
                    )}
                  </td>

                  {/* ITEM */}
                  <td>
                    {editExpense && editExpense.id === exp.id ? (
                      <input
                        type="text"
                        value={editExpense.ExpenseItem}
                        onChange={(e) =>
                          setEditExpense({
                            ...editExpense,
                            ExpenseItem: e.target.value
                          })
                        }
                      />
                    ) : (
                      exp.ExpenseItem
                    )}
                  </td>

                  {/* COST */}
                  <td>
                    {editExpense && editExpense.id === exp.id ? (
                      <input
                        type="number"
                        value={editExpense.ExpenseCost}
                        onChange={(e) =>
                          setEditExpense({
                            ...editExpense,
                            ExpenseCost: e.target.value
                          })
                        }
                      />
                    ) : (
                      exp.ExpenseCost
                    )}
                  </td>

                  {/* ACTION */}
                  <td>
                    {editExpense && editExpense.id === exp.id ? (
                      <>
                        <button
                          className="btn btn-sm btn-dark me-2"
                          onClick={handleUpdate}
                        >
                          Save
                        </button>

                        <button
                          className="btn btn-sm btn-secondary"
                          onClick={() => setEditExpense(null)}
                        >
                          Cancel
                        </button>
                      </>
                    ) : (
                      <>
                        <button
                          className="btn btn-sm btn-info me-2"
                          onClick={() => setEditExpense(exp)}
                        >
                          <i className="fas fa-edit"></i>
                        </button>

                        <button className="btn btn-sm btn-danger" onClick={() => handleDelete(exp.id)}>
                          <i className="fas fa-trash-alt"></i>
                        </button>
                      </>
                    )}
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="5" className="text-center text-muted">
                  No expenses found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <ToastContainer />
    </div>
  );
};

export default ManageExpense;